-- The data files' catalogue: vintage, domain and status of each file, kept by hand (31 October 2026: converted from
-- capri_data/MANIFEST.json, which it replaces; tools/check/validate_data.py's rules in 99_rules.sql check it). The
-- columns, types, keys and code lists of each file are in its own declaration, its origin in 01_provenance.sql and the
-- checked notes in 02_provenance_notes.sql; this table keeps what neither holds: the year or point the data stand for
-- (a file under capri_data/2017/ can hold CAPRI's 2030 reference), the domain, live or source, and the reason a
-- base-year file carries another vintage.
-- units and note are MANIFEST.json's text as it stood on 31 October 2026, written over 2-30 October and not checked
-- again when converted: a statement there is to be checked against the file before it is relied on (the checked notes
-- go to 02_provenance_notes.sql). Files written since the manifest stopped being kept have no row; a row is added
-- when a file's vintage needs saying.

CREATE TABLE file_catalogue (
    file VARCHAR PRIMARY KEY,                      -- path from the repository root
    vintage VARCHAR NOT NULL,                      -- the year or point the data stand for ('2017', '2030 reference', ...)
    domain VARCHAR NOT NULL,                       -- supply, market, prices, environment, policy, abatement, sources, ...
    status VARCHAR NOT NULL CHECK (status IN ('live', 'live (builder input)', 'source', 'calibration', 'validation',
                                              'tools')),          -- MANIFEST.json's statuses, as written
    units VARCHAR,                                 -- MANIFEST.json's units text (not re-checked)
    vintage_exception VARCHAR,                     -- why a base-year file carries another vintage
    note VARCHAR                                   -- MANIFEST.json's note (not re-checked)
);
COMMENT ON TABLE file_catalogue IS 'vintage, domain and status of the data files (from MANIFEST.json, 31 October 2026; units and notes not re-checked)';
