INSERT INTO file_catalogue VALUES
  ('capri_data/2017/abatement/fert_side_effects.csv', 'jul15 data', 'environment', 'live', 'relative change of emissions', NULL, NULL),
  ('capri_data/2017/abatement/mitigation/genetics_effects.csv', '2030 reference', 'abatement', 'live', 'relative changes per unit of the technology parameter; EUR per head', NULL, 'Per unit of tech_param (ghgTechMYld / ghgTechFEff, CAPRI scenario settings, capri_mod/policy/endotech.py); scaled at run time. | 23 October 2026: column max_share, CAPRI''s MaxShare of the breeding options with %fixGenet_eff_to_iniValues% on (0.002, breeding.gms l. 65-77, lowered to the max calibration run''s level where smaller, l. 375-379), applied with the endotech setting fixGenetToIni. dsav: CAPRI''s cost-saving drop between its ini and max calibration runs, EUR per model head adopting (per unit of the parameter; tools/lib/_capri_costsavings.py), netted from the PMP slope as CAPRI (K67 F2).'),
  ('capri_data/2017/abatement/mitigation/lownfeed_effects.csv', '2017 base / 2030 calibration', 'abatement', 'live', 'relative change; EUR/head; share', NULL, 'CAPRI''s low-nitrogen feeding per model region and animal (envind/low_n_feed.gms): protein requirement and manure N change per unit of ghgTechLowNFeed, eligible share, cost, calibration terms; tools/build/build_lownfeed_effects.py. dsav: CAPRI''s cost-saving drop between its ini and max calibration runs, EUR per model head adopting (per unit of the parameter; tools/lib/_capri_costsavings.py), netted from the PMP slope as CAPRI (K67 F2).'),
  ('capri_data/2017/abatement/mitigation/supplement_effects.csv', '2017 base / 2030 calibration', 'abatement', 'live', 'relative change; EUR/head; share', NULL, 'CAPRI''s feed supplements linseed (LINE_Tot) and nitrate (Nitr_Tot) per model region and cattle animal (envind/line_nitr.gms, ghgTechLineNitr a switch): requirement changes, eligible share, cost, CH4ENT change, calibration terms; tools/build/build_supplement_effects.py. dsav: CAPRI''s cost-saving drop between its ini and max calibration runs, EUR per model head adopting (per unit of the parameter; tools/lib/_capri_costsavings.py), netted from the PMP slope as CAPRI (K67 F2).; 3-NOP rows (3NOP_Tot) since 29 October 2026 (K93)'),
  ('capri_data/2017/abatement/mitigation/winter_cover_option.csv', '2030', 'abatement', 'live', 'share; EUR/ha', NULL, 'tools/build/build_winter_cover_option.py'),
  ('capri_data/2017/environment/climate_zones.csv', 'static', 'environment', 'live', 'category', NULL, NULL),
  ('capri_data/2017/environment/fert_dist_crop_groups_2030.csv', '2030 reference', 'environment', 'live', 'share', NULL, 'Model crop -> CAPRI crop group (NGRP) with area shares per CAPRI region (OFOD = OFAR + ROOF, OLIV = OLIV + TABO, GRAS = GRAE + GRAI); tools/build/build_fert_dist_priors.py.'),
  ('capri_data/2017/environment/fert_dist_priors_2030.csv', '2030 reference', 'environment', 'live', 'kg N/ha; 1000 ha; shares', NULL, 'Priors of CAPRI''s inner fertiliser distribution model (supply/set_fert_priors.gms, simulation: baseline posterior mode per ha, accuracy 1): per CAPRI region and crop group the mineral, manure and residue N per ha, area, mineral efficiency and manure availability; tools/build/build_fert_dist_priors.py, docs/FERTILISER_ALLOCATION.md.'),
  ('capri_data/2017/environment/fertiliser_substitution_2030.csv', '2030', 'environment', 'live', 'share', NULL, 'Manure-N availability and mineral-N efficiency per region (CAPRI fertiliser allocation): manure displaces mineral fertiliser at availability/efficiency; need_at_floor_share: share of crop need at CAPRI''s minimum-mineral floor (fert/fertpar.gms p_minShareMinFert: 0.4 arable, 0.5 vegetables/permanent, 0.3 maize, 0.2 silage maize, 0.05 grass, 0 pulses), EU median where unmatched'),
  ('capri_data/2017/environment/histosol.csv', '2017', 'environment', 'live', 'share; kg N2O-N/ha; t/ha; EUR/ha', NULL, NULL),
  ('capri_data/2017/environment/irrigation_2017.csv', '2017 (FSS survey up to 2017)', 'environment', 'live', 'share (irrigated_share, irr2_share), mm (cnir_mm)', NULL, 'Read by capri_mod/water (indicator outside the run).'),
  ('capri_data/2017/environment/livestock_manure_n_coef.csv', '2017', 'environment', 'live', 'kg N/head', NULL, 'Manure N per head (kg), CAPRI 2017 regional manure N total per activity divided by this model''s herd (census stock) | Rebuilt 2026-10 with the corrected NUTS correspondence (73 regions now regional CAPRI values). | Norway''s pig cells rebuilt 21 October 2026 (tools/build/build_norway_pigs.py --rebuild)'),
  ('capri_data/2017/environment/manure_n2o_factors.csv', '2017', 'environment', 'live', 't N2O-N per t manure N', NULL, NULL),
  ('capri_data/2017/environment/manure_n2o_tech.csv', '2017', 'environment', 'live', 'relative reduction', NULL, NULL),
  ('capri_data/2017/environment/manure_pool_centres.csv', 'CAPRI star 3.0', 'environment', 'calibration', '-', NULL, 'The centre region of each manure pool (rManPool_centre); converted from JSON on 31 October 2026 (capri_mod/data/nested_tables.py), the same values.'),
  ('capri_data/2017/environment/manure_pool_costs.csv', 'CAPRI star 3.0', 'environment', 'calibration', 'km; EUR per t N', NULL, '34 country pools, 930 connected pairs; used only with use_manure_market (off). With manure_pool_centres.csv; converted from JSON on 31 October 2026 (capri_mod/data/nested_tables.py), the same values.'),
  ('capri_data/2017/environment/manure_trade_2030.csv', '2030', 'environment', 'live', 'share; kg N/ha', NULL, 'CAPRI''s 2030 manure N trade between regions: export share of excretion, import per ha of cropland; counts only where the run trades manure (manureTradeNew).'),
  ('capri_data/2017/environment/n_deposition_regional.csv', '2030', 'environment', 'live', 'kg N/ha', NULL, 'Atmospheric N deposition per ha by region (CAPRI 2030 reference, EMEP-based); 157 NUTS-2, 91 national. Deposition changes slowly; 2030 used for the 2017 base.'),
  ('capri_data/2017/environment/nh3_factors_capri.csv', '2030 reference', 'environment', 'live', 'kg NH3-N per kg N excreted', NULL, 'Ammonia shares of excreted N per animal (GNH3/MANN, weighted by excreted N); the mineral N shares (NH3MIN/MINFER) in nh3_factors_capri_regions.csv; converted from JSON on 31 October 2026 (capri_mod/data/nested_tables.py), the same values.'),
  ('capri_data/2017/environment/nh3_factors_capri_regions.csv', '2030 reference', 'environment', 'live', 'kg NH3-N per kg N applied', NULL, 'Ammonia share of mineral N (NH3MIN/MINFER) per region, the factors'' source (regional or national) and CAPRI''s NH3 total; converted from JSON on 31 October 2026 (capri_mod/data/nested_tables.py), the same values.'),
  ('capri_data/2017/environment/p_balance_crop_coefs_2030.csv', '2030 reference', 'environment', 'live', 'kg P2O5/ha; 1000 ha', NULL, 'CAPRI''s P2O5 removal (retention) and crop residue output per ha of the model''s crops, per CAPRI region (GRAE and GRAI also on their own), for the gross phosphate balance of the environmental accounts (EnvironmentalModule.compute_phosphorus_balance); tools/build/build_p_balance.py, docs/P_BALANCE.md. At CAPRI''s own areas the coefficients give its EXPPRD and CRESID (PHOF) exactly.'),
  ('capri_data/2017/feed/feed_ration_2017.csv', '2017', 'feed', 'calibration', 'kg/head/yr; per head per yr; per kg; EUR/kg', NULL, 'EU ration data per region x animal: base ration by feed group, energy/protein/dry-matter requirements, nutrient contents, feed prices, CAPRI''s feed-PMP slopes (2017 and 2030 calibration), one value per row (block, feed, nutrient). Input to the EU ration choice (docs/FEED_RATION.md). | converted from JSON on 31 October 2026 (capri_mod/data/nested_tables.py), the same values.'),
  ('capri_data/2017/feed/fodder_balance_2017.csv', '2017', 'feed', 'live', 't/ha; EUR/t', NULL, 'Regional fodder balances (645 in 221 regions), exact at base (docs/FODDER_BALANCE.md); the fodder per head in fodder_balance_2017_use.csv; converted from JSON on 31 October 2026 (capri_mod/data/nested_tables.py), the same values.'),
  ('capri_data/2017/feed/fodder_balance_2017_use.csv', '2017', 'feed', 'live', 't/head', NULL, 'Fodder per head per animal of each fodder balance; converted from JSON on 31 October 2026 (capri_mod/data/nested_tables.py), the same values.'),
  ('capri_data/2017/feed/livestock_feed_coef.csv', '2017', 'feed', 'live', 't/head', NULL, 'Feed per head (t): cereals, protein-rich and energy-rich feed - CAPRI 2017 regional totals (FCER/FPRO/FENE x LEVL) divided by this model''s herd | Rebuilt 2026-10 with the corrected NUTS correspondence (73 regions now regional CAPRI values). | Norway''s pig cells rebuilt 21 October 2026 (tools/build/build_norway_pigs.py --rebuild)'),
  ('capri_data/2017/market/armington_rho.csv', 'code', 'market', 'live', '-', NULL, 'Armington substitution elasticities of the two nests per market commodity Sprint 9f: + FRMI, CREM, COCM, WMIO, CASE (CAPRI''s dairy products, traded).'),
  ('capri_data/2017/market/bilateral_flows_2017.csv', '2017', 'market', 'live', 'kt; EUR/t', NULL, 'CAPRI''s bilateral flows aggregated to the model''s trade regions (the EU as CAPRI''s two market regions EU_WEST, EU_EAST since 3 November 2026; the one-EU files and their _eu2 twins merged) with the import price split into exporter-price part a and fixed part b (tools/build/build_bilateral_market.py) Sprint 9f: + FRMI, CREM, COCM, WMIO, CASE (CAPRI''s dairy products, traded).'),
  ('capri_data/2017/market/bilateral_flows_2030.csv', '2030 reference', 'market', 'live', 'kt; EUR/t', NULL, 'as bilateral_flows_2017.csv for the 2030 market year Sprint 9f: + FRMI, CREM, COCM, WMIO, CASE (CAPRI''s dairy products, traded).'),
  ('capri_data/2017/market/bilateral_regions_2017.csv', '2017', 'market', 'live', 'EUR/t; kt', NULL, 'market price and production per model trade region (the EU as CAPRI''s two market regions EU_WEST, EU_EAST since 3 November 2026; the one-EU files and their _eu2 twins merged) Sprint 9f: + FRMI, CREM, COCM, WMIO, CASE (CAPRI''s dairy products, traded).'),
  ('capri_data/2017/market/bilateral_regions_2030.csv', '2030 reference', 'market', 'live', 'EUR/t; kt', NULL, 'market price and production per model trade region, 2030 Sprint 9f: + FRMI, CREM, COCM, WMIO, CASE (CAPRI''s dairy products, traded).'),
  ('capri_data/2017/market/bilateral_trq_2017.csv', '2017', 'market', 'live', 'kt; %; EUR/t', NULL, 'CAPRI''s bilateral tariff-rate quotas of every importer per pair of policy blocks, with their regime (docs/design/PORTS_STAGE4.md)'),
  ('capri_data/2017/market/bilateral_trq_global_2017.csv', '2017', 'market', 'live', 'kt; %; EUR/t', NULL, 'CAPRI''s global tariff-rate quotas per importer block, with the free-trade exporters (docs/design/PORTS_STAGE4.md)'),
  ('capri_data/2017/market/bilateral_trq_2030.csv', '2030 reference', 'market', 'live', 'kt; %; EUR/t', NULL, 'CAPRI''s bilateral tariff-rate quotas of every importer per pair of policy blocks, with their regime (docs/design/PORTS_STAGE4.md)'),
  ('capri_data/2017/market/bilateral_trq_global_2030.csv', '2030 reference', 'market', 'live', 'kt; %; EUR/t', NULL, 'CAPRI''s global tariff-rate quotas per importer block, with the free-trade exporters (docs/design/PORTS_STAGE4.md)'),
  ('capri_data/2017/market/border_measures_2030.csv', '2030 reference', 'market', 'live', 'EUR/t', NULL, 'CAPRI''s entry prices and flexible levies (docs/design/PORTS_STAGE4.md, stage 6)'),
  ('capri_data/2017/market/border_pairs_2030.csv', '2030 reference', 'market', 'live', 'EUR/t', NULL, 'CAPRI''s entry price pairs'),
  ('capri_data/2017/market/policy_blocks.csv', 'code', 'market', 'live', NULL, NULL, 'each market region''s CAPRI policy block'),
  ('capri_data/2017/market/raw_milk_prices_2017.csv', '2017', 'market', 'live', 'EUR/t', NULL, 'CAPRI''s raw milk market price per market region'),
  ('capri_data/2017/market/raw_milk_prices_2030.csv', '2030 reference', 'market', 'live', 'EUR/t', NULL, 'CAPRI''s raw milk market price per market region'),
  ('capri_data/2017/market/biofuel_feedstock_2017.csv', '2017 market year', 'market', 'live', 'kt; t/t; EUR/t', NULL, 'First-generation biofuel feedstocks per CAPRI market region and biofuel (all regions; column region = model trade region): 2030-reference quantity, biofuel and by-product yields, feedstock and by-product prices, numeraire, CES elasticity (tools/build/build_biofuel_market.py). Reproduces CAPRI''s BiofFeedCost exactly in every region.'),
  ('capri_data/2017/market/biofuel_feedstock_2030.csv', '2030 market year', 'market', 'live', 'kt; t/t; EUR/t', NULL, 'First-generation biofuel feedstocks per CAPRI market region and biofuel (all regions; column region = model trade region): 2030-reference quantity, biofuel and by-product yields, feedstock and by-product prices, numeraire, CES elasticity (tools/build/build_biofuel_market.py). Reproduces CAPRI''s BiofFeedCost exactly in every region.'),
  ('capri_data/2017/market/biofuel_market_2017.csv', '2017 market year', 'market', 'live', 'kt; EUR/t; share; toe/t', NULL, 'CAPRI''s biofuel supply (SupplyBiof_), demand (biofDemShare_, biofDem_) and non-fuel processing (ProcNQ_: proc_kt, proc_hess from p_hessNQProc, INPE price) functions per CAPRI market region, calibrated as biofuel/def_biofuel_params.gms to the 2030 reference; tools/build/build_biofuel_market.py, docs/BIOFUEL_MARKET.md.'),
  ('capri_data/2017/market/biofuel_market_2030.csv', '2030 market year', 'market', 'live', 'kt; EUR/t; share; toe/t', NULL, 'CAPRI''s biofuel supply (SupplyBiof_), demand (biofDemShare_, biofDem_) and non-fuel processing (ProcNQ_: proc_kt, proc_hess from p_hessNQProc, INPE price) functions per CAPRI market region, calibrated as biofuel/def_biofuel_params.gms to the 2030 reference; tools/build/build_biofuel_market.py, docs/BIOFUEL_MARKET.md.'),
  ('capri_data/2017/market/biofuel_use_share_2017.csv', '2017 market year', 'market', 'live', 'kt; share', NULL, 'Share of the EU use of each model market commodity that goes to biofuels (tools/build/build_biofuel_market.py).'),
  ('capri_data/2017/market/biofuel_use_share_2030.csv', '2030 market year', 'market', 'live', 'kt; share', NULL, 'Share of the EU use of each model market commodity that goes to biofuels (tools/build/build_biofuel_market.py).'),
  ('capri_data/2017/market/dairy_eu_balance.csv', '2030 reference', 'market', 'live', 'kt; elasticity', NULL, 'EU27 balance of the nine dairy products (production, food, feed, industry, losses, processing, extra-EU net imports) and HCOM-weighted own-price demand elasticity. Sums of the EU27 member states (Norway left out since 21 October 2026, K56).'),
  ('capri_data/2017/market/dairy_eu_demand_elas.csv', '2030 reference', 'market', 'live', 'elasticity', NULL, 'EU food demand elasticities among the nine dairy products, own and cross (dairy Stage 3).'),
  ('capri_data/2017/market/dairy_hessian.csv', '2030 reference', 'market', 'live', 'kt per (EUR/t / INPE)', NULL, 'Hessian of CAPRI''s dairy normalised quadratic production function per member state; reproduces CAPRI''s p_ElasDair own-price elasticities (max difference 7e-5). EU member states only since 21 October 2026 (Norway, NO000000, is in dairy_world_processing.csv as trade region NOR: KNOWN_ISSUES K56).'),
  ('capri_data/2017/market/dairy_processing.csv', '2030 reference', 'market', 'live', 'kt; %; EUR/t', NULL, 'CAPRI''s dairy block per member state: quantities, processing, fat and protein contents, prices, raw milk, fat and protein prices (tools/build/build_dairy_processing.py). EU member states only since 21 October 2026 (Norway, NO000000, is in dairy_world_processing.csv as trade region NOR: KNOWN_ISSUES K56).'),
  ('capri_data/2017/market/dairy_world_baseline.csv', '2030 reference', 'market', 'live', 'kt', NULL, 'World base balances of the dairy products (BUTR, SKIM, CHES, WHEY, FRMI, CREM, COCM, WMIO, CASE) per model trade region (tools/build/build_dairy_world_markets.py); converted from JSON on 31 October 2026 (capri_mod/data/nested_tables.py), the same values.'),
  ('capri_data/2017/market/dairy_world_demand_elas.csv', '2030 reference', 'market', 'live', 'elasticity', NULL, 'Food demand elasticities among the nine dairy products, non-EU market regions.'),
  ('capri_data/2017/market/dairy_world_hessian.csv', '2030 reference', 'market', 'live', 'kt per (EUR/t / INPE)', NULL, 'Dairy NQ Hessians of the non-EU market regions.'),
  ('capri_data/2017/market/dairy_world_processing.csv', '2030 reference', 'market', 'live', 'kt; %; EUR/t', NULL, 'CAPRI''s dairy block data for the 54 non-EU market regions (53 before Norway was its own, K56) with a dairy Hessian, mapped to the model''s trade regions; row MILKSUP = raw milk supply slope (dairy Stage 4, tools/build/build_dairy_world_blocks.py). Norway (NO000000) included as trade region NOR since 21 October 2026 (K56): its raw milk from its supply models in the market.'),
  ('capri_data/2017/market/eu_cake_feed_bas.csv', '2017', 'supply', 'live', '1000 t', NULL, 'the EU''s base-period feed use of RAPC, SUNC, SOYC: the weights of the protein-feed cake index'),
  ('capri_data/2017/market/eu_market_supply_nq.csv', '2030 calibration point', 'market', 'live', 'kt per unit change of the price ratio (h_ratio); h in kt per EUR/t over INPE', NULL, 'CAPRI''s market supply functions (ProdNQ_) of the EU products no supply model produces (tools/build/build_eu_market_supply_nq.py); they reproduce CAPRI''s p_elasSupp at the calibration point; the Hessian completed as CAPRI''s market model completes it on loading (tools/lib/_capri_nq.py: symmetric; 29 October 2026, K98)'),
  ('capri_data/2017/market/eu_ms_balance_2030.csv', '2030 calibration point', 'market', 'live', 'kt', NULL, 'splits EU-level market data without member-state detail between the EU trade blocks (tools/build/build_eu_ms_balance.py); EU totals stay those of their own sources (2030 Green Deal reference)'),
  ('capri_data/2017/market/feed_bulks_eu.csv', '2030 reference', 'market', 'live', 'kt; EUR/t', NULL, 'CAPRI''s feed bulks of the member states (FCER cereals, FPRO protein-rich feed): per member state and bulk the market products'' 2030 feed use, EU Arm1 prices and the CES elasticity (feedBlkPrice_, feedShareEqu_; tools/build/build_feed_bulks.py). Products sum to CAPRI''s bulk totals.'),
  ('capri_data/2017/market/feed_bulks_eu_share.csv', '2030 reference', 'market', 'live', 'kt; share', NULL, 'Feed share of EU use per model commodity in the bulks (CAPRI 2030 reference FEED / (HCOM+FEDM+INDM+BIOF+LOSM)); tools/build/build_feed_bulks.py.'),
  ('capri_data/2017/market/feed_bulks_noneu.csv', '2030', 'market', 'live', '1000 t; EUR/t', NULL, 'tools/build/build_feed_bulks.py. Norway''s feed bulks (its supply models'' bulk price indices at Norway''s prices, and its feed demand following its herds in its own market region NOR, KNOWN_ISSUES K56); use_kt = Norway''s use of the product (HCOM + FEDM + INDM + BIOF + LOSM + PRCM) for the feed share of its use'),
  ('capri_data/2017/market/feed_byproducts.csv', '2030 reference', 'market', 'live', 'kt; share', NULL, 'CAPRI''s residual feeds FENI and FPRI (MaprFeed_): EU 2030 output and the parent commodities'' weights (cereals'' food and processing use for FPRI, sugar''s food and biofuel use for FENI); tools/build/build_feed_byproducts.py (Sprint 9h).'),
  ('capri_data/2017/market/feed_demand_nonEU.csv', '2030 calibration point', 'market', 'live', 'share', NULL, 'Non-EU feed demand per trade region (ROW and the grouped regions included) for every product with a CAPRI feed function that the model trades: feed share of CAPRI''s use (HCON+FEED+PROC+BIOF); elasticities in feed_demand_nonEU_elasticities.csv, CAPRI regions in feed_demand_nonEU_capri_regions.csv (tools/build/build_feed_demand_nonEU.py); converted from JSON on 31 October 2026 (capri_mod/data/nested_tables.py), the same values.'),
  ('capri_data/2017/market/feed_demand_nonEU_capri_regions.csv', '2030 calibration point', 'market', 'live', '-', NULL, 'The CAPRI regions of each trade region''s feed function; converted from JSON on 31 October 2026 (capri_mod/data/nested_tables.py), the same values.'),
  ('capri_data/2017/market/feed_demand_nonEU_elasticities.csv', '2030 calibration point', 'market', 'live', 'elasticity', NULL, 'Feed-weighted p_ElasFeed per trade region, product and price; converted from JSON on 31 October 2026 (capri_mod/data/nested_tables.py), the same values.'),
  ('capri_data/2017/market/gl_demand_b.csv', '2030 calibration point', 'market', 'live', '-', NULL, 'GL food demand b parameters (upper triangle) per behavioural region'),
  ('capri_data/2017/market/gl_demand_goods.csv', '2030 calibration point', 'market', 'live', 'kg per head; EUR/t; kt', NULL, 'GL food demand commitments and calibration point per behavioural region (tools/build/build_gl_demand.py)'),
  ('capri_data/2017/market/gl_demand_regions.csv', '2030 calibration point', 'market', 'live', 'EUR per head; 1000 heads', NULL, 'income per head, inhabitants and the reproduction check of each behavioural region'),
  ('capri_data/2017/market/noneu_market_supply_nq.csv', '2030 calibration point', 'market', 'live', 'kt per unit change of the price ratio (h_ratio); h in kt per EUR/t over INPE', NULL, 'CAPRI''s market supply functions (ProdNQ_) of the non-EU market regions with their cross-price terms (tools/build/build_noneu_market_supply_nq.py; K54-3, market step D); the land demand rows and rent columns TCRP, FODFAL, FRUN are the land market''s (noneu_land_market.csv)'),
  ('capri_data/2017/market/noneu_land_market.csv', '2030 calibration point', 'market', 'live', '1000 ha; EUR/ha', NULL, 'CAPRI''s market land block per non-EU market region: land, rents, MNL constants and available land per land type (PORTS_STAGE4.md stage 7)'),
  ('capri_data/2017/market/noneu_land_mnl.csv', '2030 calibration point', 'market', 'live', 'per EUR/ha', NULL, 'CAPRI''s MNL land supply coefficients p_bLu per non-EU market region'),
  ('capri_data/2017/market/luc_market_priors.csv', '2030 calibration point', 'market', 'live', '1000 ha', NULL, 'CAPRI''s land-use-change estimation of the market outside the EU: priors and calibration-point transitions (luc_market)'),
  ('capri_data/2017/market/luc_market_classes.csv', '2030 calibration point', 'market', 'live', '1000 ha', NULL, 'CAPRI''s initial land per UNFCCC class (the 2025 land) of the market''s land-use-change estimation'),
  ('capri_data/2017/market/luc_market_shares.csv', '2030 calibration point', 'market', 'live', 'share', NULL, 'CAPRI''s shares linking the market''s land types to the UNFCCC land classes'),
  ('capri_data/2017/market/processing_nq_base.csv', '2030 calibration point', 'market', 'live', 'kt per EUR/t; kt', NULL, 'processing and total use per behavioural region and product, for the processing share of use'),
