  ('capri_data/2017/market/processing_yields.csv', '2030 reference', 'market', 'live', 't/t', NULL, 'olive oil per tonne of olives (member state) and milled rice per tonne of paddy (EU) (tools/build/build_processing_yields.py)'),
  ('capri_data/2017/market/market_prod_grof_2030.csv', '2030 reference', 'market', 'live', 't/t', NULL, 'CAPRI''s marketed over gross production per country with supply models and market product, grofNEprod (tools/build/build_market_prod_grof_2030.py)'),
  ('capri_data/2017/market/producer_prices.csv', '2017', 'prices', 'live', 'EUR/t', NULL, '29 October 2026: the ten livestock rows of unrecorded origin removed (read by no model code; KNOWN_ISSUES K72)'),
  ('capri_data/2017/market/sugar_processing.csv', '2030 reference', 'market', 'live', 'kt; t/t', NULL, 'White sugar per tonne of beet harvested (tools/build/build_sugar_processing.py); beet price follows the sugar price (arm/set_prices.gms).'),
  ('capri_data/2017/market/supply_elas_eu.csv', '2017', 'market', 'live', 'elasticity', NULL, 'the EU rows'' own-price supply elasticity: median over the model''s 27 member states per market commodity'),
